  1	/// An item a policy covers, as the office records it: the type it is listed
  2	/// under in the price list, and the properties its clauses judge. The office
  3	/// records an item's material because its reimbursement clauses speak of
  4	/// items made of dragon material, and it is on the record of every insured
  5	/// item whatever the clauses do with it. No clause reads the material: the
  6	/// dragon-material clause reimburses in full, which is already what the
  7	/// office admits when no clause reduces the damage, and where the clause
  8	/// meets the enchantment clause the enchantment clause wins -- see
  9	/// `reimbursable_damage_of`.
 10	pub struct Item {
 11	    pub item_type: String,
 12	    pub cursed: bool,
 13	    pub enchantment: i64,
 14	    pub material: String,
 15	}
 16	
 17	const PROCESSING_FEE: i64 = 5;
 18	
 19	const FIRST_INSURANCE_SURCHARGE: f64 = 0.10;
 20	const CURSE_SURCHARGE: f64 = 0.50;
 21	const HIGH_ENCHANTMENT_SURCHARGE: f64 = 0.30;
 22	const LOYALTY_DISCOUNT: f64 = 0.20;
 23	const LOYALTY_YEARS: i64 = 2;
 24	const FOLLOW_UP_CONTRACT_DISCOUNT: f64 = 0.15;
 25	const HIGH_ENCHANTMENT_SURCHARGE_LEVEL: i64 = 5;
 26	
 27	const SWORD_BASE_PREMIUM: f64 = 100.0;
 28	const AMULET_BASE_PREMIUM: f64 = 60.0;
 29	const STAFF_BASE_PREMIUM: f64 = 80.0;
 30	const POTION_BASE_PREMIUM: f64 = 40.0;
 31	const COMPONENT_BASE_PREMIUM: f64 = 25.0;
 32	const SWORD_INSURANCE_VALUE: i64 = 1000;
 33	const AMULET_INSURANCE_VALUE: i64 = 600;
 34	const COMPONENT_INSURANCE_VALUE: i64 = 250;
 35	const PAYOUT_CAP_FACTOR: i64 = 2;
 36	const DEDUCTIBLE: i64 = 100;
 37	const HIGH_ENCHANTMENT_REIMBURSEMENT_LEVEL: i64 = 8;
 38	const HIGH_ENCHANTMENT_REIMBURSEMENT: f64 = 0.50;
 39	const COMPONENT_BLOCK_SIZE: usize = 3;
 40	const COMPONENT_BLOCK_BASE_PREMIUM: f64 = 60.0;
 41	
 42	/// The MHPCO treats components -- runes and moonstones -- as a category of
 43	/// their own, priced per component rather than per type. Component types enter
 44	/// this predicate with their examples.
 45	fn is_component(item: &Item) -> bool {
 46	    matches!(item.item_type.as_str(), "rune" | "moonstone")
 47	}
 48	
 49	/// The MHPCO insures the item types its price list names and no others.
 50	fn is_in_the_price_list(item_type: &str) -> bool {
 51	    matches!(
 52	        item_type,
 53	        "sword" | "amulet" | "staff" | "potion" | "rune" | "moonstone"
 54	    )
 55	}
 56	
 57	/// The MHPCO price list: the base premium in G for a single insured item. Main
 58	/// item types are listed individually; every component carries the same flat
 59	/// component premium. All four main types now have their examples, and a quote
 60	/// over an unlisted type is refused before it reaches the list, so the
 61	/// remaining arm prices the sword and nothing else -- it is written as a
 62	/// fall-through rather than as a `"sword"` arm because the list is closed and a
 63	/// `"sword"` arm would leave an unreachable residual behind it.
 64	fn base_premium_of(item: &Item) -> f64 {
 65	    if is_component(item) {
 66	        return COMPONENT_BASE_PREMIUM;
 67	    }
 68	    match item.item_type.as_str() {
 69	        "amulet" => AMULET_BASE_PREMIUM,
 70	        "staff" => STAFF_BASE_PREMIUM,
 71	        "potion" => POTION_BASE_PREMIUM,
 72	        _ => SWORD_BASE_PREMIUM,
 73	    }
 74	}
 75	
 76	/// What the customer's standing with the office is worth, as a single share of
 77	/// the policy base premium. The office was asked whether "first insurance"
 78	/// means the customer's first ever contract or the first time it sees this
 79	/// item, and ruled for the item: every item in a quote is treated as a first
 80	/// insurance, so the initial assessment surcharge is unconditional and a
 81	/// long-standing customer pays it on a brand-new sword like anyone else. What
 82	/// the years of business earn is the loyalty discount, taken against that
 83	/// surcharge. This is the office's customer-history policy, and the rest of
 84	/// the premium calculation does not need to know which clauses it is made of.
 85	fn policy_modifier_rate_of(history: &CustomerHistory) -> f64 {
 86	    let mut modifier_rate = FIRST_INSURANCE_SURCHARGE;
 87	    if history.customer.years_with_mhpco >= LOYALTY_YEARS {
 88	        modifier_rate -= LOYALTY_DISCOUNT;
 89	    }
 90	    if history.preceding_contracts > 0 {
 91	        modifier_rate -= FOLLOW_UP_CONTRACT_DISCOUNT;
 92	    }
 93	    modifier_rate
 94	}
 95	
 96	/// Policy-wide modifiers apply to the policy base premium, the sum of all item
 97	/// base premiums, at the single rate the customer's standing earns.
 98	fn with_policy_modifiers(history: &CustomerHistory, policy_base_premium: f64) -> f64 {
 99	    policy_base_premium + policy_base_premium * policy_modifier_rate_of(history)
100	}
101	
102	/// A building block of 3 alike components is offered at a special base premium
103	/// instead of the per-component price.
104	fn alike_components_base_premium(count: usize) -> f64 {
105	    if count == COMPONENT_BLOCK_SIZE {
106	        return COMPONENT_BLOCK_BASE_PREMIUM;
107	    }
108	    count as f64 * COMPONENT_BASE_PREMIUM
109	}
110	
111	/// The policy base premium is the sum of all item base premiums, except that
112	/// alike components are priced together so the block offer can apply.
113	fn policy_base_premium_of(items: &[Item]) -> f64 {
114	    let main_items: f64 = items
115	        .iter()
116	        .filter(|item| !is_component(item))
117	        .map(base_premium_of)
118	        .sum();
119	    let components: f64 = alike_component_groups_of(items)
120	        .into_iter()
121	        .map(alike_components_base_premium)
122	        .sum();
123	    main_items + components
124	}
125	
126	/// Components count as alike when they are of exactly the same type, not
127	/// merely of the same family: a policy of 2 runes and 1 moonstone forms no
128	/// block, so the office prices the two kinds separately. This groups a
129	/// policy's components by type and reports how many are in each group, in
130	/// order of the groups' first appearance.
131	fn alike_component_groups_of(items: &[Item]) -> Vec<usize> {
132	    let mut groups: Vec<(&str, usize)> = Vec::new();
133	    for item in items.iter().filter(|item| is_component(item)) {
134	        match groups.iter_mut().find(|(alike, _)| *alike == item.item_type) {
135	            Some((_, count)) => *count += 1,
136	            None => groups.push((&item.item_type, 1)),
137	        }
138	    }
139	    groups.into_iter().map(|(_, count)| count).collect()
140	}
141	
142	/// Only the final premium is rounded, and a premium is rounded up -- the
143	/// MHPCO's favor for money it collects. The processing fee is added at the very
144	/// end; being a whole number of G, it does not affect the rounding.
145	fn total_premium_of(premium_before_fee: f64) -> i64 {
146	    premium_before_fee.ceil() as i64 + PROCESSING_FEE
147	}
148	
149	/// The office was asked whether a risk surcharge on one item of a multi-item
150	/// policy burdens the whole policy, and ruled that it does not: an
151	/// item-specific modifier is measured against the base premium of the affected
152	/// item alone. A policy of a cursed sword and a plain amulet therefore carries
153	/// a curse surcharge of 50 G -- 50 % of the sword's own 100 G base premium --
154	/// and not 80 G, half of the 160 G policy base premium.
155	fn item_surcharges_of(items: &[Item]) -> f64 {
156	    items.iter().map(item_surcharge_of).sum()
157	}
158	
159	/// The risk surcharges an item carries: a curse adds 50 %, an enchantment at
160	/// or above the surcharge level adds 30 %, and an item that is both carries
161	/// both. The surcharge level is the premium side's own threshold; the claim
162	/// side judges enchantment against a separate level of its own.
163	fn item_surcharge_of(item: &Item) -> f64 {
164	    let mut surcharge_rate = 0.0;
165	    if item.cursed {
166	        surcharge_rate += CURSE_SURCHARGE;
167	    }
168	    if item.enchantment >= HIGH_ENCHANTMENT_SURCHARGE_LEVEL {
169	        surcharge_rate += HIGH_ENCHANTMENT_SURCHARGE;
170	    }
171	    base_premium_of(item) * surcharge_rate
172	}
173	
174	/// How the two modifier families stack. By the office's scope ruling they are
175	/// measured against different bases, so they cannot be combined into one
176	/// percentage: the policy-wide modifiers scale the policy base premium, while
177	/// the item surcharges are shares of their own items' base premiums and are
178	/// added alongside. A cursed sword is therefore 100 + 10 % of 100 + 50 % of
179	/// 100, not 10 % of 150; a cursed sword beside a plain amulet is 160 + 10 % of
180	/// 160 + 50 % of 100.
181	fn premium_before_fee_of(history: &CustomerHistory, items: &[Item]) -> f64 {
182	    with_policy_modifiers(history, policy_base_premium_of(items)) + item_surcharges_of(items)
183	}
184	
185	/// The single customer a scenario's policies belong to.
186	pub struct Customer {
187	    pub years_with_mhpco: i64,
188	}
189	
190	/// The office's view of the customer at the moment of a quote: who they are
191	/// and how many contracts they already hold. The preceding-contract count is
192	/// not a property of the customer -- a scenario has one customer whose steps
193	/// are processed in order, so the count is what the office has on file when
194	/// this particular quote is drawn up. Together these are the facts the
195	/// customer-history policy reads.
196	pub struct CustomerHistory<'a> {
197	    pub customer: &'a Customer,
198	    pub preceding_contracts: usize,
199	}
200	
201	/// The MHPCO price list: the insurance value in G of a single insured item --
202	/// the worth the office acknowledges when it pays out, as opposed to the price
203	/// it charges to carry the risk. The price list prints the two figures side by
204	/// side, but they are separate rulings and move separately: the block offer and
205	/// the premium modifiers both change what an item costs to insure while leaving
206	/// its acknowledged worth untouched. So this list stays apart from the base
207	/// premium list rather than being derived from it. Unlike the base premium
208	/// list, this one is still incomplete: the staff and the potion have no
209	/// acknowledged worth on file yet, so the remaining arm still stands in for
210	/// them as well as for the sword, and awaits their examples.
211	fn insurance_value_of(item: &Item) -> i64 {
212	    if is_component(item) {
213	        return COMPONENT_INSURANCE_VALUE;
214	    }
215	    match item.item_type.as_str() {
216	        "amulet" => AMULET_INSURANCE_VALUE,
217	        _ => SWORD_INSURANCE_VALUE,
218	    }
219	}
220	
221	/// The insurance sum is the sum of the insured items' insurance values. The
222	/// block offer discounts the premium only, never the insurance sum.
223	fn insurance_sum_of(items: &[Item]) -> i64 {
224	    items.iter().map(insurance_value_of).sum()
225	}
226	
227	/// One item's damage reported in an incident.
228	pub struct Damage {
229	    pub item_type: String,
230	    pub amount: i64,
231	}
232	
233	/// What the office settles on a claim: the payout in G and the cap still
234	/// available on the policy afterwards.
235	#[derive(Debug, PartialEq, Eq)]
236	pub struct Settlement {
237	    pub payout: i64,
238	    pub remaining_cap: i64,
239	}
240	
241	/// How the office settles a claim against this policy. One incident may
242	/// damage several insured items, and the office settles each damaged item on
243	/// its own terms before adding the amounts up: a dragon attack on a sword and
244	/// an amulet is settled as two damages, not as one. The awarded sum is then
245	/// held back to the cap still available, which is the policy's cap less what
246	/// earlier claims have already drawn on it -- a policy may be claimed against
247	/// more than once, so what has been paid so far is a fact of every claim, nil
248	/// on the first.
249	pub fn claim(
250	    items: &[Item],
251	    paid_so_far: i64,
252	    damages: &[Damage],
253	) -> Result<Settlement, String> {
254	    let cap_available = payout_cap_of(items)? - paid_so_far;
255	    let payout = desired_payout_of(items, damages)?.min(cap_available);
256	    Ok(Settlement {
257	        payout,
258	        remaining_cap: cap_available - payout,
259	    })
260	}
261	
262	/// What the reimbursement clauses award for an incident, before the policy's
263	/// cap is consulted. The office settles each damaged item on its own terms and
264	/// adds the amounts up; this is the sum the office desires to pay, which the
265	/// cap may then hold back -- the spec speaks of a desired payout being reduced
266	/// to the cap remaining, so the awarded sum is a figure of its own and not
267	/// merely an intermediate step inside the cap accounting.
268	fn desired_payout_of(items: &[Item], damages: &[Damage]) -> Result<i64, String> {
269	    let mut desired_payout = 0;
270	    for damage in damages {
271	        let damaged_item = insured_item_damaged_by(items, damage)?;
272	        desired_payout += reimbursement_of(damaged_item, damage);
273	    }
274	    Ok(desired_payout)
275	}
276	
277	/// Which insured item a reported damage concerns. A damage names only an item
278	/// type, so the office looks the type up in the policy; the item it finds is
279	/// what the reimbursement clauses are then judged against, since they read the
280	/// insured item's own enchantment and material rather than anything in the
281	/// report. The office has separate rulings pending on a damage it cannot match
282	/// -- a type the policy does not cover, and more damages of a type than the
283	/// policy insures -- so for now an unmatched type yields nothing here.
284	fn insured_item_damaged_by<'a>(items: &'a [Item], damage: &Damage) -> Result<&'a Item, String> {
285	    items
286	        .iter()
287	        .find(|item| item.item_type == damage.item_type)
288	        .ok_or_else(|| format!("item not covered by the policy: {}", damage.item_type))
289	}
290	
291	/// What the office reimburses for one damaged item: the damage amount less the
292	/// deductible. The office charges the deductible per damage event, and it
293	/// counts each damaged item as a damage event of its own -- two items damaged
294	/// by a single dragon attack bear the deductible twice, once each.
295	fn reimbursement_of(damaged_item: &Item, damage: &Damage) -> i64 {
296	    reimbursable_damage_of(damaged_item, damage) - DEDUCTIBLE
297	}
298	
299	/// How much of the reported damage the office admits before the deductible --
300	/// which of its reimbursement clauses governs, and what that clause admits.
301	/// The office has two: damage to an item enchanted at or above the
302	/// reimbursement level is admitted at half, and damage to an item made of
303	/// dragon material is reimbursed in full. Only the enchantment clause appears
304	/// as a branch here, and that is the whole clause set faithfully, not a
305	/// clause left out:
306	///
307	/// - Full reimbursement IS the dragon-material outcome, and it is also what
308	///   the office admits when no clause reduces the damage. The two clauses
309	///   therefore differ in which items they name, not in what they pay, so a
310	///   separate dragon-material branch would compute the same amount the
311	///   fall-through already computes.
312	/// - Where both clauses name the same item, the halving clause governs: a
313	///   dragon-material sword enchanted at the reimbursement level is admitted at
314	///   half, not in full. Ranking the enchantment clause first is what makes the
315	///   collapse above sound, because it leaves the dragon clause reachable only
316	///   where it agrees with the fall-through.
317	///
318	/// So this stays one decision with one discriminating predicate. A third
319	/// clause, or a clause whose share were neither half nor full, would break the
320	/// collapse and force the clause set to become visible structure.
321	///
322	/// The reimbursement level is the claim side's own threshold, set higher than
323	/// the level at which the premium side charges a risk surcharge: the office
324	/// surcharges an enchantment of 5 but only halves its reimbursement from 8.
325	fn reimbursable_damage_of(damaged_item: &Item, damage: &Damage) -> i64 {
326	    let highly_enchanted =
327	        damaged_item.enchantment >= HIGH_ENCHANTMENT_REIMBURSEMENT_LEVEL;
328	    if highly_enchanted {
329	        return admitted_damage_of(damage.amount as f64 * HIGH_ENCHANTMENT_REIMBURSEMENT);
330	    }
331	    damage.amount
332	}
333	
334	/// An admitted damage is rounded down -- the MHPCO's favor for money it pays
335	/// out, the mirror of the rounding up a premium gets in `total_premium_of`.
336	/// This is the office's house-wide favor ruling, not a reimbursement clause:
337	/// it is the direction a fraction is resolved in, whatever clause produced the
338	/// fraction. Rounding sits here, at the halving clause, because that clause is
339	/// the only step of a settlement that can yield a fraction at all -- the
340	/// deductible, the insurance values and the cap are whole G throughout -- so
341	/// rounding the share the office admits and rounding the final payout are the
342	/// same figure. A clause admitting some other share would arrive here too; a
343	/// fractional deductible or cap would move the ruling to the final payout.
344	fn admitted_damage_of(admitted_share: f64) -> i64 {
345	    admitted_share.floor() as i64
346	}
347	
348	/// The total payout per policy is capped at twice the insurance sum.
349	pub fn payout_cap_of(items: &[Item]) -> Result<i64, String> {
350	    Ok(insurance_sum_of(items) * PAYOUT_CAP_FACTOR)
351	}
352	
353	/// Whether the office will entertain a policy over these items at all. The
354	/// office insures the types its price list names and no others, so an item it
355	/// does not recognise is refused rather than priced -- a quote that lists a
356	/// broomstick yields no premium. The office names the offending type in its
357	/// refusal; which types it admits is the price list's own knowledge, read
358	/// here rather than restated.
359	fn admit_the_listed_items(items: &[Item]) -> Result<(), String> {
360	    match items
361	        .iter()
362	        .find(|item| !is_in_the_price_list(&item.item_type))
363	    {
364	        Some(unlisted) => Err(format!("unknown item type: {}", unlisted.item_type)),
365	        None => Ok(()),
366	    }
367	}
368	
369	/// The premium in G the office charges for insuring these items, given what it
370	/// has on file about the customer.
371	pub fn quote(history: &CustomerHistory, items: &[Item]) -> Result<i64, String> {
372	    admit_the_listed_items(items)?;
373	    Ok(total_premium_of(premium_before_fee_of(history, items)))
374	}
375	
376	#[cfg(test)]

